from Crypto.Util.number import *
from sympy import *
from random import randint
def get_q(a):
    a = a**2
    count = 0
    for i in range(1, 11111111):
        b = randint(i, 1111111111)
        c = randint(1, i)
        if (b % c != 0):
            a += b**11
            count += b**11
    a = nextprime(a)
    return a, count

flag = b'wpst{*******}'
p = getPrime(256)
q, count = get_q(p)
n = p**2 * q
e = 0x10001
m = bytes_to_long(flag)
c = pow(m, e, n)

print(f'n = {n}')
print(f'e = {e}')
print(f'c = {c}')
print(f'count = {count}')

